import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

public class Main {
    static List<Long> a1 = new ArrayList<>();
    static List<Long> a2 = new ArrayList<>();
    static long[] a;
    static int n, m, n1;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextLong();
        }
        n1 = n / 2;

        sum1(0, 0);
        sum2(n1, 0);

        List<Long> a1Set = new ArrayList<>(a1);
        // Remove duplicates and sort
        Collections.sort(a1Set);
        List<Long> uniqueA1 = new ArrayList<>();
        Long prev = null;
        for (Long val : a1Set) {
            if (prev == null || !prev.equals(val)) {
                uniqueA1.add(val);
                prev = val;
            }
        }

        long ans = 0;
        for (Long i : a2) {
            int index = Collections.binarySearch(uniqueA1, m - i);
            if (index < 0) {
                index = -index - 1;
            }
            if (index > 0) {
                long candidate = uniqueA1.get(index - 1) + i;
                if (candidate > ans) {
                    ans = candidate;
                }
            }
        }
        System.out.println(ans);
        sc.close();
    }

    static void sum1(int i, long sum) {
        if (i == n1) {
            a1.add(sum % m);
        } else {
            sum1(i + 1, (sum + a[i]) % m);
            sum1(i + 1, sum);
        }
    }

    static void sum2(int i, long sum) {
        if (i == n) {
            a2.add(sum);
        } else {
            sum2(i + 1, (sum + a[i]) % m);
            sum2(i + 1, sum);
        }
    }
}
